// Geist + Geist Mono TTFs, base64-encoded, embedded as source.
//
// WHY base64 and not bytes: the Task 5 spike proved on the live edge runtime
// that `Font.register({ src: <Uint8Array> })` FAILS — react-pdf coerces the
// value to a string and treats it as a filesystem path, throwing
// `NotFound: path not found: /var/tmp/sb-compile-edge-runtime/source`.
// A `data:font/ttf;base64,...` URI is the working in-memory form. The edge
// runtime has no filesystem access to bundled assets, so this is the only
// way to ship the fonts.
//
// Source: .superpowers/sdd/fonts (Geist, SIL Open Font License 1.1).
// Generated, not hand-written — regenerate with `base64 -i <file>` if the
// fonts are ever updated.

/** Geist-Regular.ttf (168064 base64 chars). */
export const GEIST_REGULAR_B64 =
  "";

/** Geist-Medium.ttf (170216 base64 chars). */
export const GEIST_MEDIUM_B64 =
  "";

/** Geist-SemiBold.ttf (170496 base64 chars). */
export const GEIST_SEMIBOLD_B64 =
  "";

/** GeistMono-Regular.ttf (198024 base64 chars). */
export const GEIST_MONO_REGULAR_B64 =
  "";
